import scala.collection.mutable.HashSet

def containsDuplicate(numbers: Array[Int]): Boolean = {
  val seenNumbers = HashSet.empty[Int]

  for (number <- numbers) {
    if (seenNumbers.contains(number)) {
      return true
    }
    seenNumbers += number
  }

  false
}

