def minimumDifference(numbers: Array[Int]): Int = {
  val sortedNumbers = numbers.sorted
  var bestDifference = Int.MaxValue

  for (currentIndex <- 1 until sortedNumbers.length) {
    val currentDifference = sortedNumbers(currentIndex) - sortedNumbers(currentIndex - 1)
    bestDifference = math.min(bestDifference, currentDifference)
  }

  bestDifference
}

import scala.collection.mutable.ArrayBuffer

def spiralOrder(matrix: Array[Array[Int]]): Array[Int] = {
  val result = ArrayBuffer.empty[Int]
  var topRow = 0
  var bottomRow = matrix.length - 1
  var leftColumn = 0
  var rightColumn = matrix(0).length - 1

  while (topRow <= bottomRow && leftColumn <= rightColumn) {
    for (columnIndex <- leftColumn to rightColumn) {
      result += matrix(topRow)(columnIndex)
    }
    topRow += 1

    for (rowIndex <- topRow to bottomRow) {
      result += matrix(rowIndex)(rightColumn)
    }
    rightColumn -= 1

    if (topRow <= bottomRow) {
      for (columnIndex <- rightColumn to leftColumn by -1) {
        result += matrix(bottomRow)(columnIndex)
      }
      bottomRow -= 1
    }

    if (leftColumn <= rightColumn) {
      for (rowIndex <- bottomRow to topRow by -1) {
        result += matrix(rowIndex)(leftColumn)
      }
      leftColumn += 1
    }
  }

  result.toArray
}

import scala.collection.mutable.ArrayBuffer

def hasValidBrackets(text: String): Boolean = {
  val stack = ArrayBuffer.empty[Char]
  val openingByClosing = Map(')' -> '(', ']' -> '[', '}' -> '{')

  for (character <- text) {
    if (openingByClosing.values.toSet.contains(character)) {
      stack += character
    } else if (openingByClosing.contains(character)) {
      if (stack.isEmpty || stack.last != openingByClosing(character)) {
        return false
      }
      stack.remove(stack.length - 1)
    }
  }

  stack.isEmpty
}

import scala.collection.mutable.HashMap

def hasSubarrayWithTargetSum(numbers: Array[Int], target: Int): Boolean = {
  var runningSum = 0L
  val firstIndexByPrefixSum = HashMap[Long, Int](0L -> -1)

  for (currentIndex <- numbers.indices) {
    runningSum += numbers(currentIndex)
    val requiredPrefixSum = runningSum - target

    if (firstIndexByPrefixSum.contains(requiredPrefixSum)) {
      return true
    }

    if (!firstIndexByPrefixSum.contains(runningSum)) {
      firstIndexByPrefixSum(runningSum) = currentIndex
    }
  }

  false
}

def transpose(matrix: Array[Array[Int]]): Array[Array[Int]] = {
  val rowCount = matrix.length
  val columnCount = matrix(0).length
  val result = Array.ofDim[Int](columnCount, rowCount)

  for (rowIndex <- 0 until rowCount; columnIndex <- 0 until columnCount) {
    result(columnIndex)(rowIndex) = matrix(rowIndex)(columnIndex)
  }

  result
}

