def hasPairWithTargetSum(sortedNumbers: Array[Int], target: Int): Boolean = {
  var leftIndex = 0
  var rightIndex = sortedNumbers.length - 1

  while (leftIndex < rightIndex) {
    val currentSum = sortedNumbers(leftIndex) + sortedNumbers(rightIndex)

    if (currentSum == target) {
      return true
    } else if (currentSum < target) {
      leftIndex += 1
    } else {
      rightIndex -= 1
    }
  }

  false
}

