import scala.collection.mutable.HashMap

def twoSum(numbers: Array[Int], target: Int): Array[Int] = {
  val indexBySeenNumber = HashMap.empty[Int, Int]

  for (currentIndex <- numbers.indices) {
    val currentNumber = numbers(currentIndex)
    val requiredNumber = target - currentNumber

    indexBySeenNumber.get(requiredNumber) match {
      case Some(previousIndex) =>
        return Array(previousIndex, currentIndex)
      case None =>
        indexBySeenNumber(currentNumber) = currentIndex
    }
  }

  Array.empty[Int]
}

