def longestWindowUnderTarget(numbers: Array[Int], target: Int): Int = {
  var leftIndex = 0
  var currentWindowSum = 0
  var bestWindowLength = 0

  for (rightIndex <- numbers.indices) {
    currentWindowSum += numbers(rightIndex)

    while (leftIndex <= rightIndex && currentWindowSum >= target) {
      currentWindowSum -= numbers(leftIndex)
      leftIndex += 1
    }

    val currentWindowLength = rightIndex - leftIndex + 1
    bestWindowLength = math.max(bestWindowLength, currentWindowLength)
  }

  bestWindowLength
}
